<script setup lang="ts">
import { refreshFeedback as vRefreshFeedback } from '../../../shared/directives/refreshFeedback';
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {invoke,useI18n} from '../uiPorts';
import {Play,Pause,RefreshCw} from '@lucide/vue';
const props=defineProps<{projectId?:number;refreshVersion?:string;archived?:boolean}>();
const emit=defineEmits<{changed:[]}>();
const {tr}=useI18n();
type Conflict={kind:string;identity:string;hosts:string[];hostCount?:number;detail:string;decision:string;revision:number};
type View={roots:string[];run:null|{id:string;status:string;enabled:boolean;continuous:boolean;intervalSeconds:number;workers:number;counts:Record<string,number>;operations:number;reason:string;nextCheckAt?:number};events:{kind:string;target:string;outcome:string;detail:string;at:number}[];conflicts:Conflict[]};
const data=ref<View>(),error=ref(''),readError=ref(''),busy=ref(false),continuous=ref(true),interval=ref(60),workers=ref(4);
let generation=0,sequence=0,disposed=false,timer:ReturnType<typeof setTimeout>|undefined,signature='';
let readFlight:{generation:number;sequence:number;promise:Promise<void>}|undefined;
const run=computed(()=>data.value?.run),active=computed(()=>!!run.value&&['running','waiting','waiting_storage','pausing'].includes(run.value.status));
const conflicts=computed(()=>data.value?.conflicts.filter(c=>c.decision==='pending')||[]);
const states=computed<Record<string,string>>(()=>({running:tr('正在补证','Gathering evidence'),waiting:tr('持续监测中','Monitoring'),waiting_storage:tr('等待本地存储，自动重试','Waiting for local storage; retrying automatically'),pausing:tr('正在保存并暂停','Saving and pausing'),paused:tr('已暂停，可继续','Paused; can resume'),completed:tr('本轮已完成','Run completed'),interrupted:tr('已中断，可继续','Interrupted; can resume'),scope_changed:tr('范围变化，需重新启动','Scope changed; restart required')}));
const kinds=computed<Record<string,string>>(()=>({ct:'CT',dns_a:'DNS A',dns_aaaa:'DNS AAAA',dns_cname:'CNAME',tls:tr('TLS 证书','TLS certificate')}));
function schedule(g=generation){clearTimeout(timer);if(!disposed&&!props.archived&&!document.hidden&&g===generation&&active.value)timer=setTimeout(()=>void load(g),run.value?.status==='waiting'?10000:2500);}
function load(g=generation):Promise<void>{
 const p=props.projectId;if(!p||disposed||g!==generation||busy.value||document.hidden)return Promise.resolve();
 if(readFlight?.generation===g&&readFlight.sequence===sequence)return readFlight.promise;
 const seq=++sequence,flight={generation:g,sequence:seq,promise:Promise.resolve()};
 flight.promise=(async()=>{try{const v=await invoke<View>('enrichment_action',{projectId:p,action:'status',args:{}});if(disposed||g!==generation||seq!==sequence)return;data.value=v;readError.value='';const next=JSON.stringify([v.run?.id,v.run?.counts?.done,v.events?.[0]?.at,v.events?.[0]?.target]);if(signature&&signature!==next)emit('changed');signature=next;}catch(e){if(!disposed&&g===generation&&seq===sequence)readError.value=String(e);}finally{if(readFlight===flight)readFlight=undefined;if(g===generation&&seq===sequence)schedule(g);}})();
 readFlight=flight;return flight.promise;
}
async function control(action:string,conflict?:Conflict){if(busy.value||props.archived||!props.projectId||disposed)return;const g=generation;sequence++;readFlight=undefined;clearTimeout(timer);busy.value=true;error.value='';let failed=false;try{const args=action==='start'?{continuous:continuous.value,intervalSeconds:interval.value*60,workers:workers.value}:conflict?{kind:conflict.kind,identity:conflict.identity,expectedRevision:conflict.revision,decision:'acknowledged'}:{taskId:run.value?.id};const value=await invoke<View>('enrichment_action',{projectId:props.projectId,action,args});if(g!==generation||disposed)return;data.value=value;readError.value='';emit('changed');}catch(e){if(g===generation&&!disposed){error.value=String(e);failed=true;}}finally{if(g===generation&&!disposed){busy.value=false;if(failed)void load(g);else schedule(g);}}}
watch(()=>props.projectId,()=>{generation++;sequence++;clearTimeout(timer);data.value=undefined;busy.value=false;error.value='';readError.value='';signature='';void load();},{immediate:true});
watch(()=>props.refreshVersion,()=>void load());
function visibilityChanged(){if(document.hidden)clearTimeout(timer);else void load();}
onMounted(()=>document.addEventListener('visibilitychange',visibilityChanged));
onUnmounted(()=>{disposed=true;generation++;readFlight=undefined;clearTimeout(timer);document.removeEventListener('visibilitychange',visibilityChanged);});
</script>
<template>
<section class="continuous-discovery" :aria-label="tr('自动补证与持续发现','Automatic evidence and continuous discovery')">
<header><div><h4>{{tr('自动补证与持续发现','Automatic evidence and continuous discovery')}}</h4><p>{{tr('本地证书 → CT 新名称 → DNS / CNAME → TLS 证书 → 新种子，自动循环并逐项保存。','Local certificates → new CT names → DNS / CNAME → TLS certificates → new seeds, looping automatically and saving each item.')}}</p></div><span class="status">{{archived?tr('已归档，只读','Archived, read-only'):run?states[run.status]||run.status:tr('尚未启动','Not started')}}</span></header>
<p class="scope">{{tr('已确认范围：','Confirmed scope: ')}}<strong>{{data?.roots?.join(tr('、',', '))||tr('尚未设置，请先保存确认域名范围','Not set. Save a confirmed domain scope first.')}}</strong></p>
<div v-if="!archived&&(!run||['completed','scope_changed'].includes(run.status))" class="controls">
<label>{{tr('检查间隔','Check interval')}}<select v-model.number="interval" :disabled="busy"><option :value="15">{{tr('15 分钟','15 min')}}</option><option :value="60">{{tr('1 小时','1 hour')}}</option><option :value="360">{{tr('6 小时','6 hours')}}</option><option :value="1440">{{tr('24 小时','24 hours')}}</option></select></label>
<label>{{tr('并发','Concurrency')}}<select v-model.number="workers" :disabled="busy"><option v-for="n in [1,2,4,8]" :key="n" :value="n">{{n}}</option></select></label>
<label class="check"><input v-model="continuous" type="checkbox" :disabled="busy"/>{{tr('持续检查新线索（运行中重启后继续）','Keep checking for new leads (resumes after a restart)')}}</label>
<button class="button primary compact" :disabled="busy||!data?.roots?.length" @click="control('start')"><Play :size="14"/>{{tr('开始自动补证','Start evidence gathering')}}</button>
</div>
<div v-else-if="!archived&&run" class="controls"><button v-if="active" class="button secondary compact" :disabled="busy||run.status==='pausing'" @click="control('pause')"><Pause :size="14"/>{{run.status==='pausing'?tr('正在暂停…','Pausing…'):tr('暂停自动补证','Pause evidence gathering')}}</button><button v-else class="button primary compact" :disabled="busy" @click="control('resume')"><Play :size="14"/>{{tr('从断点继续','Resume from checkpoint')}}</button><span>{{tr(`${run.continuous?'持续发现':'单轮补证'} · 并发 ${run.workers} · 间隔 ${run.intervalSeconds/60} 分钟`,`${run.continuous?'Continuous discovery':'Single pass'} · Concurrency ${run.workers} · Every ${run.intervalSeconds/60} min`)}}</span></div>
<div v-if="run" class="progress" role="status"><span>{{tr('已完成','Done')}} <b>{{run.counts.done||0}}</b></span><span>{{tr('排队','Queued')}} <b>{{run.counts.pending||0}}</b></span><span>{{tr('执行','Running')}} <b>{{run.counts.running||0}}</b></span><span>{{tr('错误待重试','Awaiting retry')}} <b>{{run.counts.retry||0}}</b></span><span>{{tr('失败待处理','Failed, needs action')}} <b>{{run.counts.failed||0}}</b></span><span>{{tr('已跳过','Skipped')}} <b>{{run.counts.skipped||0}}</b></span><span>Hunter <b>{{tr('0 积分','0 points')}}</b></span></div>
<p v-if="run" class="reason">{{run.reason}} <small>{{tr(`任务 ${run.id.slice(0,8)}`,`Task ${run.id.slice(0,8)}`)}}</small></p>
<p class="explanation">{{tr('仅处理已确认范围。范围外 CNAME 保留关系；通配符不是已发现主机。自动处理缺证与网络重试；证书身份冲突才汇总复核。不会恢复隔离 / 回收资产，不读取页面，不调用 Hunter 或逐条调用模型。CT / DNS 使用现有网络配置；TLS 证书每日复查。','Only the confirmed scope is processed. Out-of-scope CNAMEs keep their relationships; wildcards are not discovered hosts. Missing evidence and network retries are handled automatically; only certificate identity conflicts are grouped for review. Quarantined or trashed assets are never restored, pages are not read, and neither Hunter nor the model is called per item. CT / DNS use the existing network settings; TLS certificates are rechecked daily.')}}</p>
<details v-if="conflicts.length"><summary>{{tr(`需要复核的身份冲突 · ${conflicts.length} 组（最多预览 20 组）`,`Identity conflicts to review · ${conflicts.length} groups (up to 20 previewed)`)}}</summary><article v-for="c in conflicts" :key="c.kind+c.identity"><code>{{c.identity}}</code><p>{{c.hosts.join(tr('、',', '))}}<span v-if="c.hostCount&&c.hostCount>c.hosts.length">{{tr(` 等 ${c.hostCount} 个主机`,` and more (${c.hostCount} hosts in total)`)}}</span></p><p>{{c.detail}}</p><button class="button secondary compact" :disabled="busy||archived" @click="control('review_conflict',c)">{{tr('已阅，保留证据','Reviewed, keep evidence')}}</button></article></details>
<details v-if="data?.events?.length"><summary>{{tr('最近执行与详细错误','Recent runs and error details')}}</summary><article v-for="(e,i) in data.events" :key="i" :class="{failed:e.outcome==='error'||e.outcome==='failed'}"><strong>{{kinds[e.kind]||e.kind}} · {{e.outcome==='failed'?tr('永久错误或已达到重试上限','Permanent error or retry limit reached'):e.outcome==='error'?tr('未成功，退避重试','Unsuccessful; retrying with backoff'):tr('已保存','Saved')}}</strong><code>{{e.target}}</code><p>{{e.detail}}</p><small>{{new Date(e.at*1000).toLocaleString()}}</small></article></details>
<footer><span>{{tr('缺少证据不等于无关，查询失败不等于资产不存在。','Missing evidence does not mean unrelated, and a failed lookup does not mean the asset does not exist.')}}</span><button v-refresh-feedback="{scope:projectId,error:readError}" class="button ghost compact" :disabled="busy" @click="load()"><RefreshCw :size="13"/>{{tr('刷新进度','Refresh progress')}}</button></footer>
<p v-if="error" role="alert" class="form-error">{{error}}</p>
<p v-if="readError" role="alert" class="form-error">{{readError}}</p>
</section>
</template>
<style scoped>
.continuous-discovery{border:1px solid var(--line);border-radius:var(--radius-md);padding:20px;margin-bottom:16px;min-width:0;background:var(--app-surface,var(--ui-surface));font-size:var(--text-body);line-height:1.7}.continuous-discovery header{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:flex-start}h4{font-size:var(--text-heading);margin:0 0 6px}p{margin:6px 0;color:var(--muted)}.status{padding:2px 8px;background:var(--app-bg,var(--ui-surface-raised));border:1px solid var(--line);border-radius:var(--radius-sm);white-space:nowrap}.scope{overflow-wrap:anywhere}.scope strong{color:var(--text)}.controls{display:flex;align-items:flex-end;flex-wrap:wrap;gap:12px;margin:14px 0}.controls label{display:flex;flex-direction:column;gap:6px;min-width:85px}.controls select{width:100%;min-height:34px;font-size:var(--text-body)}.controls .check{flex-direction:row;align-items:center;gap:8px;min-height:34px}.check input{width:15px;height:15px;min-height:0;flex:0 0 15px}.progress{display:flex;gap:8px 20px;flex-wrap:wrap;padding:10px 12px;background:var(--app-bg,var(--ui-surface-raised));border:1px solid var(--line);border-radius:var(--radius-sm)}.progress b{margin-left:6px}.reason small{margin-left:10px}.explanation{font-size:var(--text-meta)}details{margin-top:12px}summary{cursor:pointer;color:var(--muted)}article{padding:10px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}code{display:block;font-size:var(--text-meta);overflow-wrap:anywhere}.failed strong{color:color-mix(in srgb, var(--amber) 82%, var(--ui-ink))}footer{display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap;margin-top:10px;color:var(--muted);font-size:var(--text-meta)}@media(max-width:600px){.continuous-discovery{padding:14px}.controls>.button{width:100%}.controls .check{flex-basis:100%}}
</style>
